        int n = sc.nextInt();
        int m = sc.nextInt();

        boolean[][] friends = new boolean[n + 1][n + 1];

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            friends[x][y] = true;
            friends[y][x] = true;
        }

        int count = 0;

        for (int x = 1; x <= n; x++) {
            for (int y = 1; y <= n; y++) {
                for (int z = 1; z <= n; z++) {
                    if (x != y && y != z && x != z) {
                        if (friends[x][y] && friends[y][z] && !friends[x][z]) {
                            count++;
                        }
                    }
                }
            }
        }

        System.out.println(count);
    }
}
